contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy, "param");
        uint256 beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(beforeBal == 0, "precondition: caller balance is zero");
        require(address(c).balance == 0, "precondition: c holds no Ether");

        c.withdraw(); if (__ESBMC_reverted()) return;
        uint256 afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(afterBal == 0 && address(c).balance == 0);
    }

    receive() external payable {}
}

