        c = new keepMyEther();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        vm.assume(beforeBal == 0);
        vm.assume(address(c).balance == 0);
        try c.withdraw() {} catch { return; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal == 0 && address(c).balance == 0);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
